/**
 ******************************************************************************
 * @file    jack_fx.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) made effect-file jobs resumable, exactly or by a rebuild with a pre-roll and the carry (30 Oct 2026, with an AI coding assistant).
 * @brief   Glue between the effect-file job engine (fx_job.c, pure) and
 *          FxRenderTask: the chunk block, the two render queues, and the
 *          effect part of Jack's status.
 *
 * RTOS role: runs only in JackStorageTask (osPriorityNormal), called from
 * jack_audio_sd.c. It uses:
 *   fxChunkPool          the ONE FxChunk_t (2 604 B). Whoever holds the
 *                        pointer owns the block (slide 31): Jack allocates
 *                        it and fills in[]; while a request is out it
 *                        belongs to FxRenderTask; the reply hands it back
 *                        and Jack frees it. "Home" below means back in
 *                        fxChunkPool, free to allocate again.
 *   fxRenderReqQueue     FxRenderReq_t, Jack -> FxRenderTask, put with
 *                        timeout 0: one request is out at most and the
 *                        queue holds two, so a put cannot find it full.
 *   fxRenderReplyQueue   FxRenderReply_t, FxRenderTask -> Jack (read by the
 *                        loop in jack_audio_sd.c, handed to jack_fx_reply).
 *
 * One effect file, from start to finish (the job lifecycle):
 *   1. The background (Jack idle or paused) or a PLAY of an effect not made
 *      yet starts a job in fx_job.c for one (recording, effect) pair.
 *   2. The job makes the folders FX and FX/<EFFECT>, removes a left-over
 *      NAME.TMP and the old NAME.WAV, opens the recording, checks the free
 *      space and creates NAME.TMP: one card step per loop pass.
 *   3. J_RUN, repeated: read 8 KB of the recording; send 512 samples
 *      (jack_fx_send below: the chunk block goes to FxRenderTask); take the
 *      reply (jack_fx_reply below); write up to 16 KB of effect samples.
 *   4. The real header is written and both files closed, then NAME.TMP is
 *      renamed NAME.WAV: from now on the file counts as made.
 *   5. If the user was waiting (Preparing), jack_audio_sd.c plays it now.
 *   Any time Jack needs the card or the buffer for something else (PLAY,
 *   REC, DELETE, an effect switch, a quiet remount) he parks the job
 *   (jack_fx_park below): it carries on later from where it stopped,
 *   exactly, or, if FxRenderTask made another file meanwhile, rebuilt: a
 *   short pre-roll, then the chunk where it stopped with FX_REQ_RESTORE and
 *   the job's carry (jack_fx_send copies it into the chunk block; every
 *   reply brings FxRenderTask's carry back, which jack_fx_reply hands on).
 *
 * One chunk between the two tasks (never more than one out at a time):
 *
 *   JackStorageTask (Normal)                          FxRenderTask (Idle, the lowest)
 *   1. take the fxChunkPool block, fill in[]
 *   2. put FxRenderReq_t ---- fxRenderReqQueue ---->  3. wake up, run the effect:
 *      (meanwhile: commands, 2-tick waits)               in[] -> out[]
 *   5. get the reply <---- fxRenderReplyQueue ------  4. put FxRenderReply_t
 *      copy out[], free the block
 *
 * Why FxRenderTask is at osPriorityIdle: it is the only task that uses the
 * CPU flat out, so it must never delay another task (the screen, the
 * audio). It gets every cycle the others leave; JackStorageTask blocks 2
 * ticks per pass while a request is out, so it never takes those cycles.
 * One exception: while a park waits (at most 50 ms) for the job's chunk, it
 * runs just above TonyTask (jack_fx_park below explains why).
 ******************************************************************************/
#include "jack_fx.h"
#include "fx_store.h"
#include "fx_render.h"       /* only for the checks below: the pre-roll rule's numbers are Tom's */
#include <string.h>

/* The engine keeps its own copies of numbers that live in app_rtos.h (its
 * host build cannot include it). A change on either side stops the build
 * here, so the two can never drift apart: for example, Tom adding 1 to
 * FX_RENDER_VERSION without Jack's copy would otherwise keep every old
 * effect file as if it were still valid. */
_Static_assert(FXP_CHUNK_IN == FX_RENDER_CHUNK_IN, "chunk in");
_Static_assert(FXP_CHUNK_OUT == FX_RENDER_CHUNK_OUT, "chunk out");
_Static_assert(FXP_BLOCK_SAMPLES == AUDIO_BLOCK_SAMPLES, "block size");
_Static_assert(FXP_FLAG_FIRST == FX_REQ_FIRST, "first-chunk flag");
_Static_assert(FXP_FLAG_LAST == FX_REQ_LAST, "last-chunk flag");
_Static_assert(FXP_FLAG_RESTORE == FX_REQ_RESTORE, "restore flag");
_Static_assert(FXJ_CARRY_BYTES == FX_CARRY_BYTES, "carry size: move Jack's copy too");
_Static_assert(FXJ_PREROLL_GRID_OUT == FX_RENDER_PREROLL_GRID_SAMPLES, "pre-roll grid: move Jack's copy too");
_Static_assert(FXJ_PREROLL_SHORT_OUT == FX_RENDER_PREROLL_SHORT_SAMPLES, "short pre-roll: move Jack's copy too");
_Static_assert(FXJ_PREROLL_LONG_OUT == FX_RENDER_PREROLL_LONG_SAMPLES, "long pre-roll: move Jack's copy too");
_Static_assert(FXJ_RENDER_VERSION == FX_RENDER_VERSION, "render version: move Jack's copy too");
_Static_assert(FXJ_STATUS_OK == FX_STATUS_OK, "status ok");
_Static_assert(FXJ_STATUS_BAD_REQUEST == FX_STATUS_BAD_REQUEST, "status bad request");
_Static_assert(FXJ_STATUS_NO_ENGINE == FX_STATUS_NO_ENGINE, "status no engine");
_Static_assert(FXS_EFFECT_COUNT + 1U == UI_EFFECT_COUNT, "six effects");
_Static_assert(FXS_EFFECT_NONE == UI_EFFECT_NONE, "no effect");
_Static_assert(FXS_EFFECT_AUTOTUNE == UI_EFFECT_1, "effect 1 = Autotune");
_Static_assert(FXS_EFFECT_PITCHUP == UI_EFFECT_2, "effect 2 = Pitch up");
_Static_assert(FXS_EFFECT_PITCHDN == UI_EFFECT_3, "effect 3 = Pitch down");
_Static_assert(FXS_EFFECT_ROBOT == UI_EFFECT_4, "effect 4 = Robot");
_Static_assert(FXS_EFFECT_ECHO == UI_EFFECT_5, "effect 5 = Echo");
_Static_assert(FXS_EFFECT_REVERB == UI_EFFECT_6, "effect 6 = Reverb");
_Static_assert(FXS_NAME_LEN == STORAGE_NAME_LEN, "8.3 name length");
_Static_assert(FXS_RATE_HZ == AUDIO_DAC_FS, "effect files at the DAC rate");
_Static_assert(JACK_FX_STAGE_IN_OFFSET + FXP_READ_SAMPLES * 2U <= JACK_FX_STAGE_OUT_OFFSET, "stage_in fits");
_Static_assert(JACK_FX_STAGE_OUT_OFFSET + FXP_STAGE_OUT_SAMPLES * 2U <= JACK_FX_SD_BUF_BYTES, "stage_out fits");
_Static_assert(JACK_FX_SCRATCH_OFFSET + FXJ_SCRATCH_BYTES <= JACK_FX_STAGE_IN_OFFSET, "scratch fits");

/* fxj_ops_t.send: allocate the chunk block, copy the samples into it (and,
 * for a RESTORE chunk, the job's carry) and put the request. False (nothing
 * sent, the engine tries again 2 ms later) when the block is not home or the
 * queue is full: both are impossible by construction (one request out at
 * most), so only a bug could cause them. */
static bool jack_fx_send(void *ctx, const fxj_req_t *req)
{
    (void)ctx;
    FxChunk_t *chunk = (FxChunk_t *)osMemoryPoolAlloc(fxChunkPool, 0U);
    if (chunk == NULL) return false;                  /* the block is not home: try again later */
    memcpy(chunk->in, req->in, (size_t)req->n_in * sizeof(int16_t));
    if ((req->flags & FXP_FLAG_RESTORE) != 0U) {
        if (req->carry != NULL) {
            memcpy(chunk->carry, req->carry, FX_CARRY_BYTES);   /* FxRenderTask loads it first */
        } else {
            memset(chunk->carry, 0, FX_CARRY_BYTES);            /* "no carry": FxRenderTask refuses it */
        }
    }
    const FxRenderReq_t msg = {
        .chunk   = chunk,
        .job     = req->job,
        .n_in    = req->n_in,
        .effect  = req->effect,
        .src_48k = req->src_48k,
        .flags   = req->flags,
        .pad     = 0U,
    };
    if (App_RTOS_Put(fxRenderReqQueue, &msg, 0U, &g_rtos_dropped.fx_render) != osOK) {
        (void)osMemoryPoolFree(fxChunkPool, chunk);   /* the block comes home at once */
        return false;
    }
    return true;
}

/* The engine's log hook is NULL: the firmware has no serial console (removed
 * on 1 Nov 2026). The hook stays in fx_job.h because the host tests read
 * the engine's lines through it. */
static const fxj_ops_t s_ops = { jack_fx_send, NULL, NULL };

void jack_fx_init(fxj_t *j, uint8_t *sd_buf)
{
    /* s_sd_buf is 4-byte aligned, and both stage offsets are multiples of 4:
     * the sample areas are properly aligned for int16_t. */
    int16_t *stage_in  = (int16_t *)(void *)&sd_buf[JACK_FX_STAGE_IN_OFFSET];
    int16_t *stage_out = (int16_t *)(void *)&sd_buf[JACK_FX_STAGE_OUT_OFFSET];
    fxj_init(j, &s_ops, stage_in, stage_out, &sd_buf[JACK_FX_SCRATCH_OFFSET]);
}

void jack_fx_reply(fxj_t *j, const FxRenderReply_t *rep)
{
    fxj_reply_t reply = {
        .job    = rep->job,
        .n_out  = rep->n_out,
        .status = rep->status,
        .out    = NULL,
        .carry  = NULL,
    };
    if (rep->chunk != NULL) {
        reply.out = rep->chunk->out;
        reply.carry = rep->chunk->carry;       /* FxRenderTask's carry after this chunk */
    } else {
        reply.n_out = 0U;
    }
    fxj_on_reply(j, &reply);                   /* copies the samples (and carry) of the current job's chunk */
    if (rep->chunk != NULL) {
        (void)osMemoryPoolFree(fxChunkPool, rep->chunk);   /* the block is home again */
    }
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): jack_fx_park and
 * jack_fx_park_for.
 *
 * If the job's own chunk is out, Jack BLOCKS on the reply queue (at most
 * FXJ_PARK_WAIT_TICKS) so FxRenderTask can finish it, and the job can carry
 * on exactly later. Only the job's own chunk is waited for: a late reply of
 * an older job is not, so a second park never waits again.
 *
 * Why FxRenderTask is raised for the wait: at osPriorityIdle it only gets
 * the CPU that every other task leaves. On the same button press that parks
 * the job (PLAY, REC, RESUME), TonyTask (Low) redraws the screen with
 * blocking SPI writes, which can take 20-400 ms of CPU, so FxRenderTask
 * would get nothing and the wait would run out. For the wait only, it runs
 * just above TonyTask and below every audio task, then drops
 * back to FX_RENDER_PRIORITY. (This is priority inheritance done by hand:
 * Jack, who waits, lends his urgency to the task he waits for.) */
#define JACK_FX_DRAIN_PRIORITY  osPriorityLow1    /* Low + 1: above TonyTask (Low), below BrendonTask */

static void wait_for_the_jobs_chunk(fxj_t *j)
{
    if (!fxj_job_chunk_out(j)) {
        return;
    }
    FxRenderReply_t rep;
    if (FxRenderTaskHandle != NULL) {
        (void)osThreadSetPriority(FxRenderTaskHandle, JACK_FX_DRAIN_PRIORITY);
    }
    const osStatus_t got = osMessageQueueGet(fxRenderReplyQueue, &rep, NULL, FXJ_PARK_WAIT_TICKS);
    if (FxRenderTaskHandle != NULL) {
        (void)osThreadSetPriority(FxRenderTaskHandle, FX_RENDER_PRIORITY);
    }
    if (got == osOK) {
        jack_fx_reply(j, &rep);                /* its samples go into stage_out, the block home */
    }
    /* Otherwise the chunk out is given up: the job carries on later by a
     * rebuild instead of exactly (the file is still right). */
}

void jack_fx_park(fxj_t *j)
{
    wait_for_the_jobs_chunk(j);
    fxj_park(j);                               /* staged samples written, files closed, row kept */
}

void jack_fx_park_for(fxj_t *j, const char *name, uint8_t effect)
{
    wait_for_the_jobs_chunk(j);
    fxj_park_for(j, name, effect);             /* the row of (name, effect) set aside first, then as fxj_park */
}

void jack_fx_fill_status(const fxj_t *j, bool background_allowed, uint32_t now_ms, StorageStatusMsg_t *m)
{
    fxj_status_t st;
    fxj_status(j, background_allowed, now_ms, &st);
    m->fx_busy       = st.busy ? 1U : 0U;
    m->fx_job_effect = st.job_effect;
    m->fx_job_pct    = st.job_pct;
    memcpy(m->fx_job_name, st.job_name, sizeof(m->fx_job_name));
}
